def fill_name_norm(apps, schema_editor):
    """`name_norm` у строк, залитых раньше (CSV раунда 2): короткое + полное название."""
    School = apps.get_model('problems', 'School')
    for school in School.objects.all().only('pk', 'name', 'short_name'):
        text = ' '.join(p for p in (school.short_name, school.name) if p)
        School.objects.filter(pk=school.pk).update(
            name_norm=' '.join(text.lower().replace('ё', 'е').split())[:520])


